+import type { Commit } from './git/history.js';
+
+export function findMatches(commits: Commit[], query: string): string[] {
+  const q = query.trim().toLowerCase();
+  if (!q) return [];
+  return commits.filter((c) => c.subject.toLowerCase().includes(q) || c.body.toLowerCase().includes(q)).map((c) => c.hash);
+}
+
+/** Next match in a direction, wrapping around. n goes back in time, N forward. */
+export function nextMatch(matches: string[], current: string | null, dir: 1 | -1): string | null {
+  if (!matches.length) return null;
+  const i = current ? matches.indexOf(current) : -1;
+  return matches[(i + dir + matches.length) % matches.length];
+}

