   return filter.include.size > 0 && !filter.include.has(commit.authorEmail);
 }
+
+export function toggleAuthor(filter: AuthorFilter, email: string, all: string[]): AuthorFilter {
+  const include = new Set(filter.include.size ? filter.include : all);
+  if (include.has(email)) include.delete(email);
+  else include.add(email);
+  return { include: include.size === all.length ? new Set() : include };
+}

