+/**
+ * Columns increase strictly in time-respecting topological order, so no two
+ * commits share a column and every vertical connector belongs to one commit.
+ */
+export function layout(graph: Graph, secondsPerColumn: number, order: string[]): Layout {
+  const x = new Map<string, number>();
+  let last = -1;
+  const origin = order.length ? graph.commits.get(order[0])!.committerTime : 0;
+  for (const hash of order) {
+    const c = graph.commits.get(hash)!;
+    let col = Math.max(Math.floor((c.committerTime - origin) / secondsPerColumn), last + 1);
+    for (const p of c.parents) if (x.has(p)) col = Math.max(col, x.get(p)! + 2);
+    x.set(hash, col);
+    last = col;
+  }
+  return { x, lane: new Map(), width: last + 1, lanes: graph.roots.length };
 }

