--- /dev/null
+++ b/src/graph/lanes.ts
@@ -0,0 +1,39 @@
+export interface Interval {
+  id: number;
+  start: number;
+  end: number;
+  parentLane?: number;
+}
+
+const GAP = 2;
+
+/**
+ * Greedy interval colouring. Intervals are processed by start column; each
+ * takes a free lane, so the lane count equals the maximum overlap.
+ */
+export function allocateLanes(intervals: Interval[], pinned?: number): Map<number, number> {
+  const lane = new Map<number, number>();
+  const ends: number[] = [];
+  if (pinned !== undefined) {
+    lane.set(pinned, 0);
+    ends[0] = Infinity;
+  }
+  const order = intervals.filter((i) => i.id !== pinned).sort((a, b) => a.start - b.start || a.id - b.id);
+  for (const iv of order) {
+    let chosen = -1;
+    let best = Infinity;
+    const parent = iv.parentLane ?? 0;
+    for (let l = 0; l < ends.length; l++) {
+      if (ends[l] + GAP > iv.start) continue;
+      const d = l > parent ? l - parent : parent - l + 0.5; // prefer the lane below
+      if (d < best) {
+        best = d;
+        chosen = l;
+      }
+    }
+    if (chosen === -1) chosen = ends.length;
+    lane.set(iv.id, chosen);
+    ends[chosen] = iv.end;
+  }
+  return lane;
+}

